import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-git-rewind-to-a-specific-commit":{"intro":"Git is a powerful version control system that allows developers to track changes made to their codebase. One of the most useful features of Git is the ability to rewind back to a specific commit. This can be helpful when you need to undo changes or revert to an earlier version of your code.","steps":[{"title":"Rewind to a Specific Commit","body":["As a developer, you may need to undo changes made to your codebase. For example, you may have made a mistake and need to go back to an earlier version of your code. In this challenge, you will use Git to rewind back to a specific commit in a repository.","To complete this challenge, you will use the Git repository git-playground from https://github.com/labex-labs/git-playground.git.","• View the commit history of the repository. • Make sure that the commit message you want to rewind to is the \"Initial commit\" commit hash. • Rewind back to the commit hash. • View the commit history of the repository again.","This is the result of running git log --oneline:"],"code":[{"lang":"shell","text":"c0d30f305 (HEAD -> master) Initial commit"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# Rewinds back to `3050fc0d3` but keeps changes in the working directory\n\n# Rewinds back to `c0d30f305` and deletes changes\n```\n\n```shell\ncd git-playground\ngit log --oneline\ngit reset 3050fc0d3 #the \"Initial commit\" commit hash\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-create-a-git-stash":{"intro":"In this challenge, you will learn how to use the Git stash feature to save your current changes before switching to a different branch, and then apply the stashed changes later when needed.","steps":[{"title":"Create a Git Stash","body":["As a developer, you may find yourself in a situation where you need to switch to a different branch or work on a different feature, but you're not ready to commit your changes yet. You don't want to lose your progress, but you also don't want to commit incomplete or buggy code. This is where a stash comes in handy.","A stash allows you to save your changes without committing them, so you can switch to a different branch or work on a different feature. You can then apply your stash later when you're ready to continue working on your changes.","Let's say you're working on a branch named feature in the git-playground repository and you want to save your changes before switching to a different branch:","• First, navigate to the git-playground directory. • Switch to a branch named feature. • Add the line \"Some changes\" to the README.md file. • Save your changes to a stash and add a descriptive message \"My changes\" to that stash. • Switch to a different branch. • When done making changes on the other branch, switch back to the feature branch and apply your stash."],"code":[{"lang":"shell","text":"stash@{0}: On feature: My changes"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit stash save [-u] [ < message > ]\n\ngit stash save\n# Creates a new stash\n\ngit stash save -u\n# Creates a new stash, including untracked files\n\ngit stash save \"My changes\"\n# Creates a new stash with the message \"My changes\"\ngit stash apply\n```\n\n```shell\ncd git-playground\ngit checkout -b feature\necho \"Some changes\" >> README.md\ngit stash save \"My changes\"\ngit checkout master\ngit checkout feature\ngit stash apply\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-set-default-push-branch-name":{"intro":"When working with Git, it is common to push your local changes to a remote repository. By default, Git will push your changes to a branch with the same name as your local branch. However, sometimes you may want to push your changes to a different branch. In this challenge, you will learn how to set the default push branch name to the name of the current local branch.","steps":[{"title":"Set Default Push Branch Name","body":["When pushing changes to a remote repository, Git will use the name of the current local branch as the default name for the remote branch. However, sometimes you may want to push your changes to a different branch. In this case, you would need to specify the name of the remote branch explicitly every time you push your changes. This can be tedious and error-prone, especially if you are working with multiple branches.","To complete this challenge, you will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git. Follow the steps below to set the default push branch name:","• Clone the repository from https://github.com/your-username/git-playground.git. • Change to the repository directory. • Set the default push branch name to the name of the current local branch. • Create a new branch named my-branch and switch to it. • Create a new file called hello.txt and write the string \"Hello, World\" into it. Add the newly created file hello.txt to the Git staging area and commit it, using the commit message \"Add hello.txt\" to describe the changes made in this commit. • Push your changes to the remote repository. Git will push your changes to a branch named my-branch on the remote repository.","This is the result of running git log:"],"code":[{"lang":"shell","text":"ADD hello.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config [--global] push.default current\n\ngit config --global push.default current\n\ngit checkout -b my-branch\ngit push -u\n# Pushes to origin/my-branch\n```\n\n```shell\n# Fork from https://github.com/labex-labs/git-playground.git\ngit clone https://github.com/your-username/git-playground.git\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit config push.default current\ngit checkout -b my-branch\necho \"Hello, World\" > hello.txt\ngit add hello.txt\ngit commit -m \"Add hello.txt\"\ngit push -u\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-configure-the-git-text-editor":{"intro":"When using Git, sometimes you need to write a commit message or make other changes in a text editor. By default, Git uses the system's default text editor, which may not be the one you prefer. In this challenge, you will learn how to configure the text editor used by Git.","steps":[{"title":"Configure the git text editor","body":["You want to configure the text editor used by Git to your preferred editor.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the cloned repository and configure the identity. • Configure Git to use your preferred text editor (in this example, we will use vim). • Update the contents of the hello.txt file to \"Hello, Git\" and stage it for commit. • Commit the change. • Your preferred text editor (in this example, vim) should open with the commit message. Write down your commit message \"Update hello.txt\" and save the file. • Close the text editor. The commit will be made with the message you wrote."],"code":[{"lang":"shell","text":"commit 1f19499s5387a1549f1bb5286d3d0a2b993f87e0 (HEAD -> master)\nAuthor: xiaoshengyunan <@users.noreply.github.com>\nDate:   Fri Jul 21 19:26:57 2023 +0800\n\n    Update hello.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# Sets vim as the git text editor\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit config --global core.editor \"vim\"\necho \"Hello, Git\" > hello.txt\ngit add hello.txt\ngit commit\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-sort-git-branches-by-date":{"intro":"When working with Git, it's common to have multiple branches in a repository. However, it can be difficult to keep track of all the branches and their last commit dates. In this challenge, you will learn how to use Git to sort branches by date, making it easier to manage your repository.","steps":[{"title":"Sort Git Branches by Date","body":["You have a Git repository with multiple branches, and you want to sort them by date. This will allow you to see which branches have been updated recently and which ones have not. Sorting branches by date can also help you identify branches that may need attention or merging.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Clone the repository, navigate to the directory and configure the identity. • Create a branch called one, create a file named hello.txt and commit it with the commit message \"hello.txt\". • Switch to the branch named master and create a branch named two. • Now, sort the branches by date.","This will display a list of all local branches and sort them based on the date of their last commit. You can use the arrow keys to navigate the list, and press <kbd>Q</kbd> to exit."],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch --sort=-committerdate\n```\n\n```shell\ngit clone https://github.com/labex-labs/git-playground\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b one\ntouch hello.txt\ngit add .\ngit commit -m \"hello.txt\"\ngit checkout master\ngit checkout -b two\ngit branch --sort=-committerdate\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-add-files-to-the-staging-area":{"intro":"Git is a popular version control system that allows developers to track changes made to their codebase. One of the essential features of Git is the staging area, which allows developers to selectively choose which changes to commit. In this challenge, you will learn how to add files to the staging area using Git.","steps":[{"title":"Add Files to the Staging Area","body":["You have been working on a project stored in a Git repository named https://github.com/labex-labs/git-playground. You have made some changes to the codebase and want to commit these changes to the repository. However, you only want to commit specific changes and not all the changes you have made. To do this, you need to add the files to the staging area.","• View all files in the current directory. • Suppose you have made changes to the index.html and style.css files in the git-playground directory of the git-playground repository. Add these files to the staging area. • View the status of the current working directory and staging area, including information on which files have been modified, which files have been added to the staging area, etc. • Alternatively, add all files with a .js extension in the src directory. • View the status of the current working directory and staging area again. • You can also add all changes to the staging area. • View the status of the current…","![Git staging area status](../assets/challenge-stage-files-step1-1.png)"],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# Add the files `index.html` and `style.css` to the staging area\n\n# Add all files with a `.js` extension\n\n# Adds all changes to the staging area\n```\n\n```shell\ncd git-playground\ngit add index.html style.css\ngit add *.js\ngit add .\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-return-to-previous-branch":{"intro":"In Git, branches are used to develop features or isolate changes made to the codebase. Sometimes, while working on a project, you may need to switch between different branches. In such cases, it becomes important to know how to switch back to the previous branch.","steps":[{"title":"Return to Previous Branch","body":["As a developer, you are working on a project and have switched to a different branch to work on a new feature. After making some changes, you realize that you need to switch back to the previous branch to fix a bug. You can commit your changes in a new branch and use a command to quickly switch to the previous branch.","To demonstrate how to switch back to the previous branch, you will use the Git repository git-playground from https://github.com/labex-labs/git-playground.git.","• See the status of the current branch. • Check the current branch and switch to the previous branch quickly. The name of your new branch is feature-branch and the name of the previous branch you want to switch back to is master."],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit checkout -\n```\n\n```shell\ncd git-playground\ngit checkout master\ngit checkout feature-branch\ngit checkout - # Switches to `master`\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-undo-the-last-commit":{"intro":"Git is a powerful version control system that allows developers to track changes made to their codebase. One of the most common tasks in Git is undoing a commit. This challenge will teach you how to undo the last commit without rewriting history.","steps":[{"title":"Undo the Last Commit","body":["You have just committed changes to your Git repository, but you realize that you made a mistake. You want to undo the last commit without losing any of the changes you made. How can you do this?","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Check the commit history. • Undo the last commit, creating a new commit with the inverse of the commit's changes.","This is the result of running the git log --oneline command:"],"code":[{"lang":"shell","text":"532b49b (HEAD -> master) Revert \"Added file2.txt\"\nd22f46b (origin/master, origin/HEAD) Added file2.txt\ncf80005 Added file1.txt\nb00b937 Initial commit"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit revert HEAD\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit log\ngit revert HEAD\n# Reverts the last commit\ngit log\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-remove-files-from-the-staging-area":{"intro":"In Git, the staging area is where changes to files are prepared before they are committed to the repository. Sometimes, you may accidentally add files to the staging area that you don't want to commit. In this challenge, you will learn how to remove files from the staging area using Git.","steps":[{"title":"Remove Files from the Staging Area","body":["Remove Files from the Staging Area","You are working on a project in the git-playground repository. You have made some changes to the files and added them to the staging area. However, you realize that you accidentally added a file that you don't want to commit. You need to remove this file from the staging area.","• View current working directory status. • Remove the newfile.txt file from the staging area. • Verify that the file has been removed from the staging area."],"code":[{"lang":"shell","text":"On branch master\nYour branch is ahead of 'origin/master' by 1 commit.\n(use \"git push\" to publish your local commits)\n\nChanges to be committed:\n(use \"git restore --staged <file>...\" to unstage)\nmodified: README.md\n\nUntracked files:\n(use \"git add <file>...\" to include in what will be committed)\nnewfile.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# Remove the file `newfile.txt` from the staging area\n\n# Remove all files with a `.json` extension in the `src` directory\n\n# Remove all changes from the staging area\n```\n\n```shell\ncd git-playground\ngit status\ngit restore --staged newfile.txt\ngit status\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-edit-the-last-commit":{"intro":"Git is a powerful version control system that allows developers to track changes made to their codebase. One of the most common tasks when working with Git is to edit the last commit. This can be useful when you need to make small changes to a commit that you have already made.","steps":[{"title":"Edit the Last Commit","body":["You have just committed some changes to your Git repository, but you realize that you forgot to include a file or make a small change. You don't want to create a new commit just for this small change, but you also don't want to change the commit message. How can you edit the last commit without changing its message?","To demonstrate how to edit the last commit, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the repository directory and configure your GitHub identity. • Realize that you forgot to include a file or make a small change. Add the text \"New content\" to the end of the README.md file. Add any staged changes to the last commit, without changing its message. • Verify that the last commit now includes the changes you made.","This is the content of the late commit: ![Updated commit contents screenshot](../assets/challenge-update-commit-contents.png)"],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# Edit or add files\necho \"New content\" >> README.md\ngit commit --amend --no-edit\n# The last commit includes the edited/added files\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\necho \"New content\" >> README.md\ngit add .\ngit commit --amend --no-edit\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-view-changes-between-commits":{"intro":"Git is a popular version control system that allows developers to track changes made to their codebase over time. One of the most useful features of Git is the ability to view changes between two commits. This can be helpful when trying to understand what changes were made to a codebase, or when trying to identify the cause of a bug.","steps":[{"title":"View Changes Between Commits","body":["As a developer, you have been working on a project hosted on the https://github.com/labex-labs/git-playground repository. You have made several commits to the repository, and you want to view a summary of the changes between two specific commits. However, you are not sure how to do this using Git.","Let's say you want to view the changes between the HEAD commit and the commit with the message \"Initial commit\".","Here's an example of what the output might look like:"],"code":[{"lang":"shell","text":"Hang (2):\n      Added file1.txt\n      Added file2.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit shortlog <commit>..<other-commit>\n```\n\n```shell\ncd git-playground\ngit shortlog 3050fc0de..HEAD\n#Hang (2):\n#     Added file1.txt\n#     Added file2.txt\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-view-a-visual-graph-of-the-repository":{"intro":"Git is a powerful tool for version control, allowing developers to track changes to their code over time. One of the most useful features of Git is the ability to visualize the history of a repository using a graph. This graph shows all of the commits and branches in the repository, making it easy to see how the code has evolved over time.","steps":[{"title":"View a Visual Graph of the Repository","body":["View a Visual Graph of the Repository","As a developer, you may need to view the history of a repository to understand how the code has changed over time. However, simply viewing a list of commits can be overwhelming and difficult to understand. This is where the Git graph comes in. By visualizing the history of a repository, you can quickly see how the code has evolved and identify any issues or bugs that may have been introduced.","To view a visual graph of a Git repository, let's say you want to view the history of the git-playground repository on GitHub.","• Once you have cloned the repository, you can navigate to the directory and view the graph. • Display a visual graph of all the commits and branches in the repository, allowing you to see how the code has evolved over time."],"code":[{"lang":"text","text":"* d22f46ba8c2d4e07d773c5126e9c803933eb5898 (HEAD -> master, origin/master, origin/feature-branch, origin/HEAD) Added file2.txt\n* cf80005e40a3c661eb212fcea5fad06f8283f08f Added file1.txt\n* b00b9374a7c549d1af111aa777fdcc868d8a2a01 Initial commit"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit log --pretty=oneline --graph --decorate --all\n```\n\n```shell\ncd git-playground\ngit log --pretty=oneline --graph --decorate --all\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-find-commits-that-manipulated-a-specific-str":{"intro":"Git is a powerful version control system that allows developers to track changes made to their codebase over time. One of the most useful features of Git is the ability to view the history of changes made to a specific file or even a specific line of code. In this challenge, you will learn how to use Git to find all the commits that manipulated a given string.","steps":[{"title":"Find Commits that Manipulated a Specific String","body":["Find Commits that Manipulated a Specific String","As a developer, you may need to find all the commits that modified a specific string in your codebase. For example, you may want to find all the commits that added or removed a specific function name or variable. This can be useful when debugging issues or tracking down the source of a bug.","Suppose you are working on a project hosted on GitHub called git-playground. You want to find all the commits that modified the string \"Git Playground\" in the README.md file. Here's how you can do it:","• Navigate to the repository directory. • Find all the commits that modified the string \"Git Playground\" in the README.md file and use the arrow keys to navigate through the list of commits. Press <kbd>Q</kbd> to exit the log."],"code":[{"lang":"shell","text":"commit b00b9374a7c549d1af111aa777fdcc868d8a2a01\nAuthor: Hang <huhuhang@gmail.com>\nDate:   Wed Apr 26 14:16:00 2023 +0800\n\n    Initial commit"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\n# commit c191f90c7766ee6d5f24e90b552a7d446f0d02e4\n# Author: labex\n# Date: Tue Apr 26 10:10:08 2023 +0300\n# [...]\n```\n\n```shell\ncd git-playground\ngit log -S\"Git Playground\" README.md\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-view-commits-in-a-specific-date-range":{"intro":"In this challenge, you will learn how to view commits in a specific date range using Git, which is a powerful version control system that allows developers to track changes made to their codebase.","steps":[{"title":"View Commits in a Specific Date Range","body":["View Commits in a Specific Date Range","Your task is to view all commits in a specific date range using Git. You can use either a specific date or a relative date (e.g. \"12 weeks ago\").","To complete this challenge, you will need to use the https://github.com/labex-labs/git-playground repository.","• Navigate to the repository directory. • View all commits between April 25, 2023 and April 27, 2023. • View all commits made in the last twelve weeks."],"code":[{"lang":"text","text":"commit d22f46ba8c2d4e07d773c5126e9c803933eb5898 (HEAD -> master, origin/master, origin/feature-branch, origin/HEAD)\nAuthor: Hang <huhuhang@users.noreply.github.com>\nDate:   Wed Apr 26 14:16:25 2023 +0800\n\n    Added file2.txt\n\ncommit cf80005e40a3c661eb212fcea5fad06f8283f08f\nAuthor: Hang <huhuhang@users.noreply.github.com>\nDate:   Wed Apr 26 14:16:25 2023 +0800\n\n    Added file1.txt\n\ncommit b00b9374a7c549d1af111aa777fdcc868d8a2a01\nAuthor: Hang <huhuhang@gmail.com>\nDate:   Wed Apr 26 14:16:00 2023 +0800\n\n    Initial commit"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit log [--since= [--until= < date-from > ] < date-to > ]\n\ngit log --since='Apr 25 2023' --until='Apr 27 2023'\n# commit c191f90c7766ee6d5f24e90b552a6d446f0d02e4\n# Author: labex\n# Date: Tue Apr 6 11:11:08 2023 +0300\n# [...]\n\ngit log --since='12 weeks ago'\n# commit c191f90c7766ee6d5f24e90b552a6d446f0d02e4\n# Author: labex\n# Date: Tue Apr 6 11:11:08 2023 +0300\n# [...]\n```\n\n```shell\ncd git-playground\ngit log --since='Apr 25 2023' --until='Apr 27 2023'\ngit log --since='12 weeks ago'\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-view-git-commit-summary-excluding-merges":{"intro":"When working with Git, it's important to be able to view a summary of all the commits made to a repository. However, sometimes merge commits can clutter up the output and make it difficult to see the actual changes made. In this challenge, you will learn how to view a short summary of all commits excluding merge commits.","steps":[{"title":"View a Short Summary of Commits without Merge Commits","body":["View a Short Summary of Commits without Merge Commits","You have been working on a project with several other developers, and you want to see a summary of all the commits made to the repository. However, you don't want to see the merge commits, as they don't contain any actual changes to the code. How can you view a summary of all the commits excluding merge commits?","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Navigate to the directory and configure the identity. • Create and switch to a branch called feature1, create a file called file.txt and write \"feature 1\" into it, add it to the staging area and commit it with the message \"Add feature 1\". • Switch back to the master branch, merge the feature1 branch, disable the forward merge, save and exit without changing the text. • View a short summary of all commits excluding merge commits."],"code":[{"lang":"shell","text":"430b986 (feature1) Add feature 1\nd22f46b (origin/master, origin/HEAD) Added file2.txt\ncf80005 Added file1.txt\nb00b937 Initial commit"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit log --oneline --no-merges\n```\n\n```shell\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\"\ngit checkout -b feature1\necho \"feature 1\" >> file.txt\ngit add .\ngit commit -m \"Add feature 1\"\ngit checkout master\ngit merge --no-ff feature1\ngit log --oneline\ngit log --oneline --no-merges\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-view-last-commit":{"intro":"Git is a popular version control system that allows developers to track changes in their codebase. One of the essential features of Git is the ability to view the last commit made to a repository. In this challenge, you will learn how to view the last commit made to a Git repository.","steps":[{"title":"View Last Commit","body":["You are working on a project with a team of developers, and you need to view the last commit made to the project's Git repository. You want to see the details of the commit, including the commit message, author, and date.","To view the last commit made to a Git repository, follow these steps:","The output will show you the details of the last commit, including the commit message, author, and date:"],"code":[{"lang":"shell","text":"commit d22f46ba8c2d4e07d773c5126e9c803933eb5898 (HEAD -> master, origin/master, origin/feature-branch, origin/HEAD)\nAuthor: Hang <huhuhang@users.noreply.github.com>\nDate:   Wed Apr 26 14:16:25 2023 +0800\n\n    Added file2.txt"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit log -1\n```\n\n```shell\ncd git-playground\ngit log -1\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-view-merged-branches":{"intro":"In Git, branches are used to develop features or isolate changes made to the codebase. After a branch has served its purpose, it is merged back into the main branch. However, it is important to keep track of which branches have been merged and which have not. This challenge will test your ability to view a list of all merged local branches.","steps":[{"title":"View Merged Branches","body":["Your task is to print a list of all merged local branches in the Git repository named https://github.com/labex-labs/git-playground. Once you have the list, you should be able to navigate through it using the arrow keys and exit by pressing <kbd>Q</kbd>.","• Navigate to the repository directory. • View the list of merged branches."],"code":[{"lang":"text","text":"* master\n  remotes/origin/HEAD -> origin/master\n  remotes/origin/feature-branch\n  remotes/origin/master"}]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit branch -a --merged\n```\n\n```shell\ncd git-playground\ngit branch -a --merged\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-view-the-remote-url":{"intro":"Git is a popular version control system that allows developers to manage and track changes to their code. One of the key features of Git is the ability to work with remote repositories, which are hosted on a server and can be accessed by multiple users. In this challenge, you will learn how to view the URL of a remote repository using Git.","steps":[{"title":"View the Remote URL","body":["As a developer, you may need to view the URL of a remote repository for various reasons, such as troubleshooting issues with your Git configuration or verifying that you are working with the correct repository. However, if you are not familiar with Git commands, it can be challenging to know how to view the remote URL.","For this challenge, we will be using the Git repository named https://github.com/labex-labs/git-playground. View the remote URL of this repository.","The output should display the URL of the remote repository, which in this case is https://github.com/labex-labs/git-playground.git."],"code":[]}],"commands":[],"reference":[{"path":"step1-solution.md","text":"# Solutions\n\n```shell\ngit config --get remote.origin.url\n```\n\n```shell\ncd git-playground\ngit config --get remote.origin.url\n```"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-create-a-new-repository":{"intro":"Git is a popular version control system used by developers to manage their code. One of the first steps in using Git is to create a new repository. In this lab, you will learn how to initialize a new Git repository.","steps":[{"title":"Create a New Repository","body":["We have learned how to clone an existing Git repository. Now, let's create a new Git repository from scratch.","This will create a new directory named my_repo in your current working directory and initialize a new Git repository inside it.","Let's see what inside the my_repo directory:","You should see the following files and directories:"],"code":[{"lang":"bash","text":"cd ~/project\ngit init my_repo"},{"lang":"bash","text":"ls -a my_repo"},{"lang":"plaintext","text":".  ..  .git"}]}],"commands":["cd ~/project","git init my_repo","ls -a my_repo","ls -a my_repo/.git"],"reference":[],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-tracking-bugs-in-git-codebase":{"intro":"In this lab, you will learn how to use the git bisect command to manually find the commit that introduced a bug in a Git repository by performing a binary search through the commit history.","steps":[{"title":"Manually Find the Commit that Introduced a Bug","body":["Manually Find the Commit that Introduced a Bug","Your task is to manually find the commit that introduced a bug in the git-playground repository. The repository can be found at https://github.com/labex-labs/git-playground. The bug is that the file2.txt file should print \"This is file2.txt.\" instead of \"This is file2.\".","To complete this lab, you will need to use the git bisect command to perform a binary search through the commit history of the repository. You will need to mark commits as either \"good\" (bug-free) or \"bad\" (buggy) until you have narrowed down the commit that introduced the bug.","• Change into the repository directory:"],"code":[{"lang":"text","text":"cd git-playground"},{"lang":"text","text":"git bisect start"},{"lang":"text","text":"git bisect bad HEAD"}]}],"commands":["cd git-playground","git bisect start","git bisect bad HEAD","git bisect good 3050fc0de","cat file2.txt","git bisect good","git bisect bad","git bisect reset"],"reference":[{"path":"reference.txt","text":"git bisect bad HEAD"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-git-merge-collaborative-project-management":{"intro":"Git is a powerful version control system that allows developers to work collaboratively on a project. One of the key features of Git is the ability to merge branches. Merging allows developers to combine changes from one branch into another, making it easier to manage changes and keep track of different versions of a project.","steps":[{"title":"Merge a Branch and Create a Merge Commit","body":["Merge a Branch and Create a Merge Commit","As a developer, you may need to merge a branch into the current branch, creating a merge commit. This can be a bit tricky if you're not familiar with Git. The problem is to merge a branch into the current branch, creating a merge commit, using the Git repository named https://github.com/labex-labs/git-playground directory.","For this challenge, let's use the repository from https://github.com/labex-labs/git-playground.","• Clone a repository from https://github.com/labex-labs/git-playground.git:"],"code":[{"lang":"shell","text":"git clone https://github.com/labex-labs/git-playground.git"},{"lang":"shell","text":"cd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\""},{"lang":"shell","text":"git checkout -b feature-branch"}]}],"commands":["git clone https://github.com/labex-labs/git-playground.git","cd git-playground","git config --global user.name \"your-username\"","git config --global user.email \"your-email\"","git checkout -b feature-branch","git add .","git checkout master","git merge --no-ff -m \"Merge feature-branch\" feature-branch"],"reference":[{"path":"reference.sh","text":"git checkout -b feature-branch"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-git-cherry-pick-code-changes":{"intro":"In this lab, you will learn how to use the git cherry-pick command to selectively apply changes from one commit to another branch, without merging the entire branch.","steps":[{"title":"Git Cherry-Pick","body":["As a developer, you are working on a project with multiple branches. You have identified a specific change that was made in a previous commit that you would like to apply to your current branch. However, you do not want to merge the entire branch as it contains other changes that you do not need. In this scenario, you can use the git cherry-pick command to apply the specific change to your current branch.","For this lab, let's use the repository from https://github.com/labex-labs/git-playground. Follow the steps below to complete the challenge:","• Clone the repository, navigate to the directory and configure the identity:","• Create and switch to a branch called one-branch, create a file called hello.txt, write \"hello,world\" in it, add it to the staging area and commit it with the message \"add hello.txt\":"],"code":[{"lang":"shell","text":"git clone https://github.com/labex-labs/git-playground\ncd git-playground\ngit config --global user.name \"your-username\"\ngit config --global user.email \"your-email\""},{"lang":"shell","text":"git checkout -b one-branch\necho \"hello,world\" > hello.txt\ngit add .\ngit commit -m \"add hello.txt\""},{"lang":"shell","text":"git checkout master\ngit cherry-pick 1609c283ec86ee4"}]}],"commands":["git clone https://github.com/labex-labs/git-playground","cd git-playground","git config --global user.name \"your-username\"","git config --global user.email \"your-email\"","git checkout -b one-branch","echo \"hello,world\" > hello.txt","git add .","git commit -m \"add hello.txt\"","git log","git checkout master","git cherry-pick 1609c283ec86ee4"],"reference":[{"path":"reference.sh","text":"git checkout master\ngit cherry-pick 1609c283ec86ee4"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"},"labex-git-reverting-git-commits-a-powerful-technique":{"intro":"Git is a powerful tool that allows developers to track changes to their codebase. One of the useful features of Git is the ability to rewind commits. This can be helpful when you need to undo changes or revert to a previous version of your code.","steps":[{"title":"Rewind Commits","body":["As a developer, you have been working on a project and have made several commits. However, you realize that the last few commits contain errors and you need to go back to a previous version of your code. You need to use Git to rewind your commits and get back to the previous version of your code.","To complete this lab, you will use the Git repository git-playground from your GitHub account, which comes from a fork of https://github.com/labex-labs/git-playground.git. Follow these steps:","• Clone the repository to your local machine:","• Create a new branch called rewind-commits:"],"code":[{"lang":"shell","text":"git clone https://github.com/your-username/git-playground.git\ncd git-playground"},{"lang":"shell","text":"git checkout -b rewind-commits"},{"lang":"shell","text":"git reset HEAD~1 --hard"}]}],"commands":["git clone https://github.com/your-username/git-playground.git","cd git-playground","git checkout -b rewind-commits","git log","git reset HEAD~1 --hard","git push --force origin rewind-commits"],"reference":[{"path":"reference.sh","text":"git reset HEAD~1 --hard"}],"source":"30-seconds/30-seconds-of-git · by xiaoshengyunan · CC-BY-4.0"}};
